extern int printf(const char*,...); extern int fflush(void*); extern void *stdout;
int p[24][4],nn=0,nb[24][3];void perms(int depth,int mask,int *a){if(depth==4){for(int i=0;i<4;i++)p[nn][i]=a[i];nn++;return;}for(int i=0;i<4;i++)if(!(mask>>i&1)){a[depth]=i;perms(depth+1,mask|1<<i,a);}}
int main(){int a[4];perms(0,0,a);for(int v=0;v<24;v++)for(int k=0;k<3;k++){for(int j=0;j<4;j++)a[j]=p[v][j<k+2?k+1-j:j];for(int w=0;w<24;w++){int eq=1;for(int j=0;j<4;j++)if(a[j]!=p[w][j])eq=0;if(eq)nb[v][k]=w;}}int best=0;unsigned witness=0;long hist[15]={0};for(unsigned m=0;m<(1u<<23);m++){unsigned char seen[72]={0};int f=0;for(int d=0;d<72;d++)if(!seen[d]){f++;int x=d;do{seen[x]=1;int v=nb[x/3][x%3],k=x%3;int k2=(k+((m>>v)&1?2:1))%3;x=v*3+k2;}while(!seen[x]);}hist[f]++;if(f>best){best=f;witness=m;printf("faces %d genus %d mask %u\n",best,(14-best)/2,m);fflush(stdout);}}printf("systems %u maxfaces %d witness %u\n",1u<<23,best,witness);for(int i=0;i<15;i++)if(hist[i])printf("%d %ld\n",i,hist[i]);}
